// Teste no site publicado. Uso: node teste-azure.js <fase> (publicar | conferir)
const fs = require('fs');
const os = require('os');
const path = require('path');
const base = 'https://maxx-guilherme.azurewebsites.net';
const arqSenha = path.join(os.homedir(), 'Documents', 'maxx-senha-admin.txt');
const senha = fs.readFileSync(arqSenha, 'utf8').match(/Senha: (\S+)/)[1];
const estado = path.join(__dirname, 'teste-azure.json');
const MARCA = 'TESTE AUTOMATICO - pode apagar';

let cookie = '';
async function req(metodo, caminho, corpo) {
  const opcoes = { method: metodo, redirect: 'manual', headers: { cookie } };
  if (corpo instanceof FormData) opcoes.body = corpo;
  else if (corpo) {
    opcoes.body = new URLSearchParams(corpo);
    opcoes.headers['content-type'] = 'application/x-www-form-urlencoded';
  }
  const r = await fetch(base + caminho, opcoes);
  const sc = r.headers.get('set-cookie');
  if (sc) cookie = sc.split(';')[0];
  return { status: r.status, html: await r.text(), r };
}

(async () => {
  const login = await req('POST', '/entrar', { email: 'admin@unimax.edu.br', senha });
  console.log('login:', login.status === 302 ? 'ok' : 'FALHOU ' + login.status);
  if (login.status !== 302) process.exit(1);

  if (process.argv[2] === 'publicar') {
    const form = new FormData();
    form.append('legenda', MARCA);
    form.append('imagem', new Blob([Buffer.from('89504e470d0a1a0a', 'hex')], { type: 'image/png' }), 'foto.png');
    const p = await req('POST', '/posts', form);
    console.log('post com foto:', p.status === 302 ? 'ok' : 'FALHOU ' + p.status);
    const feed = (await req('GET', '/')).html;
    const i = feed.indexOf(MARCA);
    const trecho = feed.slice(Math.max(0, i - 3000), i);
    const img = [...trecho.matchAll(/src="(\/uploads\/[^"]+)"/g)].pop()?.[1];
    const id = [...feed.slice(i - 3000, i + 3000).matchAll(/\/posts\/(\d+)/g)].map((m) => m[1])[0];
    console.log('imagem:', img, 'post id:', id);
    fs.writeFileSync(estado, JSON.stringify({ img, id }));
  } else {
    const { img, id } = JSON.parse(fs.readFileSync(estado, 'utf8'));
    const feed = (await req('GET', '/')).html;
    console.log('post continua no feed:', feed.includes(MARCA));
    const foto = await fetch(base + img, { headers: { cookie } });
    console.log('foto continua no ar:', foto.status);
    const apagar = await req('POST', `/posts/${id}/apagar`, {});
    console.log('post de teste apagado:', apagar.status === 302 && !(await req('GET', '/')).html.includes(MARCA));
  }
})();

